import React, { useState, useEffect } from "react";
import MapView from "./MapView"; // your map component
import CrimeStats from "./CrimeStats";
import Filters from "./Filters";

const App = () => {
  const [crimes, setCrimes] = useState([]);
  const [filters, setFilters] = useState({});
  const [options, setOptions] = useState({ CrimeCode: [], District: [], Neighborhood: [] });

  // Fetch crimes from backend
  useEffect(() => {
    fetch("/api/crimes")
      .then((res) => res.json())
      .then((data) => {
        setCrimes(data);

        // Build filter options dynamically
        setOptions({
          CrimeCode: [...new Set(data.map((c) => c.CrimeCode))],
          District: [...new Set(data.map((c) => c.District))],
          Neighborhood: [...new Set(data.map((c) => c.Neighborhood))],
        });
      })
      .catch((err) => console.error("Failed to fetch crimes:", err));
  }, []);

  // Apply filters
  const filteredCrimes = crimes.filter((c) => {
    return (
      (!filters.CrimeCode || c.CrimeCode === filters.CrimeCode) &&
      (!filters.District || c.District === filters.District) &&
      (!filters.Neighborhood || c.Neighborhood === filters.Neighborhood)
    );
  });

  return (
    <div style={{ display: "flex", height: "100vh" }}>
      {/* Left panel: Map + Filters */}
      <div style={{ flex: 2, display: "flex", flexDirection: "column" }}>
        <div style={{ padding: "10px", backgroundColor: "#f0f0f0" }}>
          <Filters filters={filters} setFilters={setFilters} options={options} />
        </div>
        <div style={{ flex: 1 }}>
          <MapView crimes={filteredCrimes} />
        </div>
      </div>

      {/* Right panel: Crime Stats */}
      <div style={{ flex: 1, padding: "20px", overflowY: "auto", backgroundColor: "#fafafa" }}>
        <CrimeStats crimes={filteredCrimes} />
      </div>
    </div>
  );
};

export default App;
